import { Component } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from 'src/app/service/auth.service';
import { login } from '../Models/login';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {

  constructor(private router:Router, private fb : FormBuilder, private service : AuthService){}

  signup(){
    this.router.navigate(['/register'])
  }

  loginForm = this.fb.group({
    email : ['', [Validators.required,Validators.email]],
    password : ['',[Validators.required, Validators.minLength(6)]]
  });


  onSubmit() {
this.service.login(this.loginForm.value as login).subscribe(
  (res) => {const result:any=res
    console.log(result.token);

    localStorage.setItem("token",result.token)

    localStorage.setItem("token",result.token);
    localStorage.setItem("role",result.role);
    localStorage.setItem("Id",)


    if(result.role == 'COMPANY'){
      this.router.navigate(['/company-dashboard']);
    }

    if(result.role == 'JOBSEEKER'){
this.router.navigate(["/jobseeker-dashboard"]);
    }

  }
  

);;
this.loginForm.reset();
}

}
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Log in · HireHub</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap" rel="stylesheet">


</head>
<body>
<div class="page">
<header class="topnav">
  <div class="wrap">
    <a href="index.html" class="brand"><span class="brand-dot"></span>HireHub</a>
    <nav class="nav-links">
      <a href="jobs.html">Find Jobs</a>
      <a href="companies.html">Companies</a>
      <a href="register-company.html">For Employers</a>
    </nav>
    <div class="nav-actions">
      <a routerLink="login" class="btn btn-ghost-dark btn-sm">Log in</a>
      <a (click)="signup()" class="btn btn-primary btn-sm">Sign up</a>
    </div>
  </div>
</header>

<div class="auth-wrap">
  <div class="auth-card">
    <span class="mono-label" style="color:var(--amber-dk)">Welcome back</span>
    <h2>Log in to HireHub</h2>
   <form action="" [formGroup]="loginForm" (ngSubmit)="onSubmit()">
     <div class="field"><label>Email</label><input formControlName="email" type="email" placeholder="you@email.com"></div>
    <div class="field"><label>Password</label><input formControlName="password" type="password" placeholder="••••••••"></div>
    <button  type="submit" class="btn btn-primary btn-block">Log in</button>
   </form>
    <p class="muted" style="font-size:13px;margin-top:18px;text-align:center;">No account? <a (click)="signup()" style="color:var(--indigo);font-weight:600;">Register as Job Seeker or Company</a>.</p>
  </div>
</div>

<footer class="site-footer">
  <div class="wrap">
    <span>© 2026 HireHub</span>
    <span class="mono-label" style="color:var(--muted-lt)">com.aitrich.JobPortalSystem</span>
  </div>
</footer>
</div>
</body>
</html>
